import numpy as np, json
from collections import Counter
def f(x):
    x=np.array(x); h,w=x.shape
    vals,cnts=np.unique(x,return_counts=True); bg=vals[np.argmax(cnts)]
    markers=[(i,j,int(x[i,j])) for i in range(h) for j in range(w) if x[i,j]!=bg]
    blk={(m[0],m[1]) for m in markers if m[2]==Counter(v for _,_,v in markers).most_common(1)[0][0]}
    out=x.copy()
    for i,j,v in markers:
        if (i,j) in blk: continue
        best=min((abs(bi-i)+abs(bj-j),(di,dj)) for bi,bj in blk for di,dj in ((0,1),(0,-1),(1,0),(-1,0)))
        _,di,dj=best
        ni,nj=i+di,j+dj
        while 0<=ni<h and 0<=nj<w and (ni,nj) not in blk:
            out[ni,nj]=v; ni+=di; nj+=dj
    return out.tolist()
